import type { AutoMovieViewAxis } from "../../../packages/engine/src/geometry/construction/AutoMovieViewAxis";
import type { AutoMovieViewLoft as L } from "../../../packages/engine/src/geometry/construction/AutoMovieViewLoft";
import { AutoMovieHumanConicLoft as H } from "../../../packages/human/src/generation/conic/AutoMovieHumanConicLoft";

/**
 * The stored conic family of the offline studies: the Human package's own
 * family definition and generation, so every regeneration measured here is
 * the path the figure is generated by.
 */
export namespace FamilyConicLoft {
  /** A point or direction in absolute reference coordinates. */
  export type V3 = H.V3;

  /** The complete authored definition of one part. */
  export type IStored = H.IFamily;

  /** The part's course as the engine reads it. */
  export const axis: (stored: Pick<IStored, "centres" | "halves" | "up">) => AutoMovieViewAxis.IAxis = H.axis;

  /** The family's field vector at one station. */
  export const reader: (stored: IStored) => (s: number) => number[] = H.reader;

  /** Loft a stored family through the engine at the given stations. */
  export const create: (stored: IStored, stations: number[]) => L.IResult = H.create;
}